contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address caller,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        require(caller != address(0), "zero caller");

        uint64 oldNumber = c.number();
        uint64 oldTimestamp = c.timestamp();
        uint256 oldBasefee = c.basefee();
        bytes32 oldHash = c.hash();
        uint64 oldSequenceNumber = c.sequenceNumber();
        bytes32 oldBatcherHash = c.batcherHash();
        uint256 oldL1FeeOverhead = c.l1FeeOverhead();
        uint256 oldL1FeeScalar = c.l1FeeScalar();

        bool callerIsDepositor = (caller == c.DEPOSITOR_ACCOUNT());
        bool reverted;

        if (callerIsDepositor) {
            c.setL1BlockValues(
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            );
        } else {
            try c.setL1BlockValues(
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            ) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        bool valuesUnchanged = (c.number() == oldNumber &&
            c.timestamp() == oldTimestamp &&
            c.basefee() == oldBasefee &&
            c.hash() == oldHash &&
            c.sequenceNumber() == oldSequenceNumber &&
            c.batcherHash() == oldBatcherHash &&
            c.l1FeeOverhead() == oldL1FeeOverhead &&
            c.l1FeeScalar() == oldL1FeeScalar);

        assert(!callerIsDepositor == (reverted && valuesUnchanged));
    }
}

